#!/usr/bin/env node
// Guardrail for agent-driven edits. Fails (exit 1) if the repo drifts from
// facts and rules Chanakya has fixed. Run: npm run check:invariants
//
// Do NOT edit this file to make a failure go away. A failure means: stop and
// ask Chanakya. Only Chanakya changes the allowlists below.

import { readFileSync, readdirSync, statSync, existsSync } from "node:fs";
import { join, relative } from "node:path";

const ROOT = new URL("..", import.meta.url).pathname;
const SCAN_DIRS = ["src", "public"];
const SKIP = [/routeTree\.gen\.ts$/, /\.(png|jpe?g|webp|ico|woff2?)$/];

// ---- Fixed facts (only Chanakya changes these) ----------------------------
const STUDIO_FACTS = {
  STUDIO_NAME: '"CK Builds"',
  CONTACT_EMAIL: '"nagulagamchanakya2211@gmail.com"',
  WHATSAPP_DISPLAY: '"+91 76740 40571"',
  WHATSAPP_NUMBER: '"917674040571"',
};

// Every external host the site may reference. A new host = stop and ask.
const ALLOWED_HOSTS = new Set([
  "localhost",
  "www.sitemaps.org",
  "www.w3.org",
  "api.openai.com",
  "chanakya-portfolio-orcin.vercel.app",
  "example.com", // admin form default only
  "fonts.googleapis.com",
  "fonts.gstatic.com",
  "github.com",
  "industrial-packaging-platform.vercel.app",
  "schema.org",
  "trelio.in",
  "wa.me",
]);

// Patterns that must never appear in src/ or public/.
const BANNED = [
  { re: /\bdark:/, why: "dark mode was removed (Phase 2); no dark: variants" },
  { re: /ThemeToggle|theme-toggle/, why: "theme toggle was removed (Phase 2)" },
  { re: /\b(emerald|cyan|indigo|teal|violet|purple|fuchsia|pink|rose|lime|sky|blue)-\d{2,3}\b/, why: "off-palette Tailwind hue; use ink/sage/data/surface tokens" },
  { re: /₹|\blakh\b|\bINR\s?\d/i, why: "no prices on the site" },
  { re: /SR University|B\.Tech|\bCGPA\b|\bresume\b/i, why: "no student/resume material" },
  { re: /\b15[- ]days?\b|15 business days/i, why: "no '15 days' timeline" },
  { re: /lorem ipsum|placeholder\.com|unsplash\.com|randomuser\.me|pravatar|picsum\.photos/i, why: "no placeholder or stock-people content" },
  // Lines that state a prohibition ("Never invent ... testimonials") are exempt.
  // When a real, permitted testimonial arrives (PrintFast), Chanakya adds an exemption here.
  { re: /trusted by|\d+\+?\s*(happy\s+)?clients|testimonial/i, unless: /\bNever\b/, why: "no invented social proof (see PHASE-3 plan, Rule 1)" },
];

function walk(dir, out = []) {
  if (!existsSync(dir)) return out;
  for (const name of readdirSync(dir)) {
    const p = join(dir, name);
    if (statSync(p).isDirectory()) walk(p, out);
    else if (!SKIP.some((r) => r.test(p))) out.push(p);
  }
  return out;
}

const failures = [];
const files = SCAN_DIRS.flatMap((d) => walk(join(ROOT, d)));

for (const file of files) {
  const rel = relative(ROOT, file);
  const lines = readFileSync(file, "utf8").split("\n");
  lines.forEach((line, i) => {
    for (const { re, unless, why } of BANNED) {
      if (re.test(line) && !(unless && unless.test(line))) failures.push(`${rel}:${i + 1}  ${why}\n    ${line.trim().slice(0, 140)}`);
    }
    for (const m of line.matchAll(/https?:\/\/([a-zA-Z0-9.-]+)/g)) {
      if (!ALLOWED_HOSTS.has(m[1])) {
        failures.push(`${rel}:${i + 1}  new external host "${m[1]}" is not on the allowlist — stop and ask Chanakya`);
      }
    }
  });
}

const studio = readFileSync(join(ROOT, "src/data/studio.ts"), "utf8");
for (const [key, value] of Object.entries(STUDIO_FACTS)) {
  const m = studio.match(new RegExp(`export const ${key}\\s*=\\s*([^;]+);`));
  if (!m || m[1].trim() !== value) {
    failures.push(`src/data/studio.ts  ${key} must be ${value} (found ${m ? m[1].trim() : "nothing"})`);
  }
}

if (failures.length) {
  console.error(`check-invariants: ${failures.length} problem(s)\n`);
  for (const f of failures) console.error("  ✗ " + f);
  console.error("\nDo not edit scripts/check-invariants.mjs to silence this. Fix the code or ask Chanakya.");
  process.exit(1);
}
console.log(`check-invariants: OK (${files.length} files scanned)`);
